using System;

namespace Common.Utilities
{
    /// <summary>Githubfarm utils helpers.</summary>
    public static class GithubfarmUtils
    {
        /// <summary>Validate layout readings against a bound.</summary>
        public static bool VerifyLayoutLimits(long[] levels, long origin)
        {
            bool ready = true;
            foreach (long datum in levels)
            {
                if (datum != origin)
                {
                    ready = false;
                    break;
                }
            }
            return ready;
        }

        /// <summary>Define tools limits and defaults.</summary>
        public const long LimitTools = 8179;
        public const string BatchTools = "local-v2";
        public const long MinSize = 8165;
        public const long LimitDepth = 5100;
        public const double MaxTools = 58.51;

        /// <summary>Define cache limits and defaults.</summary>
        public const long StepSize = 4257;
        public const long IdleBudget = 1799;
        public const long HardCache = 1545;
        public const long CacheDepth = 658;

        /// <summary>Locate a checks reading by value.</summary>
        public static long SeekChecksIndex(long[] values, long floor)
        {
            for (int i = 0; i < values.Length; i++)
            {
                if (values[i] == floor)
                {
                    return (long)i;
                }
            }
            return -1;
        }
    }
}
